INSERT INTO feature VALUES('corpus-expectations','corpus','Corpus expectations',NULL,'implemented','notable',NULL,'A source states each declaration''s expected verdict as `checks`, `owes`, `refuses`, `runs`, `normalizes`, `decomposes` or `reads`, and the runner settles every one with the obligations it owes; an attribute before a functor application or a module states the expectation of each name its application or header binds and refuses, and one before a data family''s member that of the declaration the member is held apart as.','surface-corpus','corpus/fragment/addressable-obligation.gandr corpus/model/desc/rules-overlap-joinable.gandr corpus/pathological/modules/functor-unexported.gandr corpus/pathological/modules/functor-mistyped.gandr corpus/pathological/desc/member-attribute.gandr corpus/pathological/desc/member-attribute-stray.gandr','corpus/model/desc/rules-overlap-joinable.gandr',NULL);
